// Certificate serial = 9 random bytes as hex (18 chars) generated by the DB
// (gen_random_bytes). Random => non-enumerable; this validates shape only.
export const SERIAL_RE = /^[a-f0-9]{18}$/;
export function isValidSerial(s: string): boolean {
  return typeof s === "string" && SERIAL_RE.test(s);
}
